"""PDF report built from a fixed template (no text is generated by AI, so nothing is invented)."""

import io
from datetime import datetime

from PIL import Image
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib.units import cm
from reportlab.platypus import Image as PdfImage
from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

DISCLAIMER = (
    "Technical demonstration only. This software is NOT a medical device and must not be "
    "used for diagnosis or clinical decisions. Results must always be reviewed by a qualified "
    "clinician."
)


def _image_flowable(array, width_cm):
    """Convert a numpy image into an element that can be placed in the PDF."""
    buffer = io.BytesIO()
    Image.fromarray(array).save(buffer, format="PNG")
    buffer.seek(0)
    return PdfImage(buffer, width=width_cm * cm, height=width_cm * cm)


def build_report(path, prediction, original, source_name, model_metrics=None,
                 dicom_fields_removed=None):
    """Write the PDF report to `path`.

    prediction: Prediction from src/inference.py
    original:   the input image as a numpy array (224 x 224, RGB)
    model_metrics: test-set metrics of the model (dict from metrics.json), optional
    """
    styles = getSampleStyleSheet()
    doc = SimpleDocTemplate(str(path), pagesize=A4, topMargin=1.5 * cm, bottomMargin=1.5 * cm)
    story = [
        Paragraph("Chest X-ray analysis report (paediatric pneumonia classifier)", styles["Title"]),
        Paragraph(DISCLAIMER, styles["Italic"]),
        Spacer(1, 0.4 * cm),
    ]

    # 1) Input and result
    rows = [
        ["Date", datetime.now().strftime("%Y-%m-%d %H:%M")],
        ["Input file", source_name],
        ["Model output", prediction.label],
        ["Probability of pneumonia", f"{prediction.probability_pneumonia:.1%}"],
        ["Decision threshold", f"{prediction.threshold:.0%}"],
        ["Attention in central (lung) region", f"{prediction.central_attention:.0%}"],
    ]
    if dicom_fields_removed is not None:
        rows.append(["DICOM anonymisation", f"{dicom_fields_removed} identifying fields removed"])
    table = Table(rows, colWidths=[7 * cm, 9 * cm])
    table.setStyle(TableStyle([
        ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
        ("BACKGROUND", (0, 0), (0, -1), colors.whitesmoke),
        ("FONTNAME", (0, 2), (1, 2), "Helvetica-Bold"),
    ]))
    story += [Paragraph("Result", styles["Heading2"]), table, Spacer(1, 0.4 * cm)]

    # 2) Images: input and Grad-CAM
    images = Table([[_image_flowable(original, 7.5), _image_flowable(prediction.heatmap, 7.5)],
                    ["Input X-ray", "Grad-CAM (red = most influential for 'pneumonia')"]])
    images.setStyle(TableStyle([("ALIGN", (0, 0), (-1, -1), "CENTER"),
                                ("FONTSIZE", (0, 1), (-1, 1), 8)]))
    story += [Paragraph("Images", styles["Heading2"]), images, Spacer(1, 0.4 * cm)]

    # 3) Quality checks of the input
    story.append(Paragraph("Input quality checks", styles["Heading2"]))
    if prediction.quality_warnings:
        for warning in prediction.quality_warnings:
            story.append(Paragraph(f"• {warning}", styles["Normal"]))
    else:
        story.append(Paragraph("No issues detected.", styles["Normal"]))

    # 4) Known performance and limitations of the model
    story.append(Paragraph("Model performance and limitations", styles["Heading2"]))
    if model_metrics:
        story.append(Paragraph(
            f"On the public test set (624 X-rays) the model had a sensitivity of "
            f"{model_metrics['sensitivity']:.1%} and a specificity of "
            f"{model_metrics['specificity']:.1%}.", styles["Normal"]))
    story.append(Paragraph(
        "Trained only on paediatric chest X-rays (1-5 years) from a single hospital; performance "
        "on other populations, devices or projections is unknown. The model does not localise or "
        "measure lesions: the heat map only shows which regions influenced its output.",
        styles["Normal"]))

    doc.build(story)
    return path
